# ---------------------------------------------------------------------------
# small linear-algebra helpers, all exact
# ---------------------------------------------------------------------------
def restrict(gram: sp.Matrix, basis: sp.Matrix) -> sp.Matrix:
    if basis.cols == 0:
        return sp.zeros(0, 0)
    return sp.expand(basis.T * gram * basis)


def kernel_basis(rows: sp.Matrix) -> sp.Matrix:
    if rows.rows == 0:
        return sp.eye(HALF)
    vectors = rows.nullspace()
    return span_matrix(vectors, HALF) if vectors else sp.zeros(HALF, 0)


def meet(left: sp.Matrix, right: sp.Matrix) -> sp.Matrix:
    """A basis of the intersection of two column spans in R^8."""
    if left.cols == 0 or right.cols == 0:
        return sp.zeros(HALF, 0)
    stack = sp.Matrix.hstack(left, -right)
    vectors = [
        sp.expand(left * sp.Matrix(v[: left.cols])) for v in stack.nullspace()
    ]
    span = span_matrix([v for v in vectors if not zero(v)], HALF)
    if span.cols == 0:
        return sp.zeros(HALF, 0)
    reduced, pivots = span.T.rref()
    return span_matrix(
        [sp.Matrix(list(reduced[k, :])) for k in range(len(pivots))], HALF
    )


def support_space(gram: sp.Matrix) -> sp.Matrix:
    slots = [
        k
        for k in range(HALF)
        if any(sp.expand(gram[k, j]) != 0 for j in range(HALF))
    ]
    return span_matrix([sp.eye(HALF)[:, k] for k in slots], HALF)


def negative_eigenspace(gram: sp.Matrix) -> sp.Matrix:
    vectors = []
    for eigenvalue, _, basis in sp.Matrix(gram).eigenvects():
        if sp.simplify(eigenvalue).is_negative is True:
            vectors.extend(sp.Matrix(v) for v in basis)
    return span_matrix(vectors, HALF)


def principal_cosines(left: sp.Matrix, right: sp.Matrix) -> tuple:
    gl = sp.expand(left.T * left)
    gr = sp.expand(right.T * right)
    cross = sp.expand(left.T * right)
    product = sp.expand(gl.inv() * cross * gr.inv() * cross.T)
    out: list = []
    for eigenvalue, multiplicity in product.eigenvals().items():
        out.extend([sp.Rational(sp.simplify(eigenvalue))] * multiplicity)
    return tuple(sorted(out, key=lambda v: -sp.Rational(v)))


def radical_quotient(form: sp.Matrix) -> tuple:
    """(dim radical, dim quotient, the induced form on a complement).

    The complement is built by greedily extending the radical to a basis with
    coordinate vectors, so the returned form IS the induced form on the
    quotient, not a lucky sub-block.
    """
    size = form.rows
    rad = form.nullspace()
    current = span_matrix(rad, size) if rad else sp.zeros(size, 0)
    current_rank = current.rank() if current.cols else 0
    complement: list = []
    for j in range(size):
        column = sp.eye(size)[:, j]
        trial = (
            sp.Matrix.hstack(current, column) if current.cols else column
        )
        if trial.rank() > current_rank:
            complement.append(column)
            current, current_rank = trial, trial.rank()
    basis = span_matrix(complement, size)
    return len(rad), basis.cols, restrict(form, basis)


def vectorise(matrix: sp.Matrix) -> sp.Matrix:
    return sp.Matrix(
        [
            matrix[i, j]
            for i in range(matrix.rows)
            for j in range(matrix.cols)
        ]
    )


# ---------------------------------------------------------------------------
# measured facts (computed once, before any mutation flag is consulted)
# ---------------------------------------------------------------------------
@dataclass(frozen=True)
class Facts:
    main_head: str
    authority: AuthorityCertificate
    # B: calibration, provenance, the committed seam object and the classes
    inertia_calibration: bool
    inertia_routes_agree: bool
    seam_reproduced: tuple
    class_split: tuple
    full_inertia_cone_wide: tuple
    # C: the incidence operator and contract C-1
    incidence_table: tuple
    incidence_selected: tuple
    hostile_controls: tuple
    clause_three: tuple
    s8_structure: tuple
    span_one_indefinite: tuple
    # D: the forced binary and the measurement
    pass_reachability: tuple
    certificate_planes: tuple
    reduced_cone_wide: tuple
    reduced_per_class: tuple
    n_versus_z: tuple
    # E: the genuinely-open attacks
    radical_quotient_table: tuple
    named_variants: tuple
    coordinate_pairs: tuple
    off_family: object
    # F: the secondary measurements
    support_route: tuple
    type_b_residue: tuple
    indefinite_pair: tuple
    s0_control: tuple
    # G: the inertness rider
    inertness: tuple
    inertness_reading: tuple
    # H / global
    correction_arithmetic: tuple
    exact_no_float: bool
    scope: dict


def measure(deep: bool) -> Facts:
    main_head = git_output("rev-parse", "origin/main")
    authority = authority_certificate(main_head)

    # -----------------------------------------------------------------------
    # calibration, in the measurement pass, on spectra known by inspection
    # -----------------------------------------------------------------------
    inertia_calibration = bool(
        congruence_inertia(sp.diag(1, 2, -3, R(5, 7))) == (3, 0, 1)
        and congruence_inertia(sp.diag(1, 1, -2, -2, 0)) == (2, 1, 2)
        and congruence_inertia(sp.diag(1, 1, 0, -1)) == (2, 1, 1)
        and congruence_inertia(sp.zeros(HALF, HALF)) == (0, HALF, 0)
        and congruence_inertia(sp.Matrix([[0, 1], [1, 0]])) == (1, 0, 1)
        and congruence_inertia(sp.Matrix([[0, -1], [-1, 0]])) == (1, 0, 1)
    )
    inertia_routes_agree = all(
        b144.congruence_inertia(probe)
        == b154.congruence_inertia(probe)
        == b156.congruence_inertia(probe)
        for probe in (
            sp.diag(1, 1, 0, -1),
            sp.diag(R(3, 32), 0, R(3, 32), 0, 0, -R(3, 32), 0, -R(3, 32)),
        )
    )

    # -----------------------------------------------------------------------
    # the committed seam Gram, rebuilt from Block 156's own constructors
    # -----------------------------------------------------------------------
    prime = herm(half(b156.THETA_PRIME_OP, b156.HQ_FREE))
    b_10, b_11, b_12, b_13, b_30, b_31, b_32, b_33 = ODD
    closed_form = sp.Matrix(
        HALF,
        HALF,
        lambda i, j: {
            (0, 0): b_30 / 4,
            (2, 2): b_32 / 4,
            (5, 5): -b_10 / 4,
            (7, 7): -b_12 / 4,
            (1, 3): (b_31 + b_33) / 8,
            (3, 1): (b_31 + b_33) / 8,
            (4, 6): -(b_11 + b_13) / 8,
            (6, 4): -(b_11 + b_13) / 8,
        }.get((i, j), 0),
    )
    seam_reproduced = (
        live_count(prime),
        zero(sp.expand(prime - closed_form)),
        tuple(k for k in range(HALF) if sp.expand(prime[k, k]) != 0),
        tuple(k for k in range(HALF) if sp.expand(prime[k, k]) == 0),
    )

    # the 16 healed edge actions, the per-edge Hermiticity systems, the classes
    differentials, star_form = b145.connection(SHEAR_X, SHEAR_T)
    edge = b145.edge_differentials(
        differentials, star_form, b156.HEALING_WEIGHTS
    )
    action = {
        key: b145.quotient_action(edge[key], b156.COVER_FREE, MASS)
        for key in EDGE_KEYS
    }
    residue = {
        key: sp.expand(action[key] - MASS * b156.HQ_FREE) for key in EDGE_KEYS
    }
    raw_rows = {
        key: hermiticity_rows(half(b156.THETA_PRIME_OP, action[key]))
        for key in EDGE_KEYS
    }
    per_edge = {key: rowspace(raw_rows[key]) for key in EDGE_KEYS}

    def stacked(subset) -> sp.Matrix:
        blocks = [per_edge[k] for k in subset if per_edge[k].rows]
        return sp.Matrix.vstack(*blocks) if blocks else sp.zeros(0, NCOORD)

    def live_dim(subset) -> int:
        stack = stacked(subset)
        if not stack.rows:
            return len(ODD)
        return sp.Matrix.vstack(stack, ODD_SELECTOR).rank() - stack.rank()

    def odd_image(subset) -> sp.Matrix:
        stack = stacked(subset)
        kernel = (
            stack.nullspace()
            if stack.rows
            else [sp.eye(NCOORD)[:, j] for j in range(NCOORD)]
        )
        projected = [sp.Matrix([v[i] for i in ODD_INDEX]) for v in kernel]
        span = span_matrix(projected, len(ODD))
        if not span.cols:
            return sp.zeros(HALF, 0)
        reduced, pivots = span.T.rref()
        return span_matrix(
            [sp.Matrix(list(reduced[k, :])) for k in range(len(pivots))], HALF
        )

    singles = tuple(k for k in EDGE_KEYS if live_dim((k,)) > 0)
    pairs = tuple(
        s for s in itertools.combinations(singles, 2) if live_dim(s) > 0
    )
    classes = tuple((k,) for k in singles) + pairs

    even_x = span_matrix([sp.eye(HALF)[:, j] for j in (0, 2, 4, 6)], HALF)
    odd_x = span_matrix(
        [
            sp.Matrix([0, 1, 0, 1, 0, 0, 0, 0]),
            sp.Matrix([0, 0, 0, 0, 0, 1, 0, 1]),
        ],
        HALF,
    )
    type_a = tuple(s for s in classes if same_space(odd_image(s), even_x))
    type_b = tuple(s for s in classes if same_space(odd_image(s), odd_x))
    class_split = (
        len(classes),
        len(type_a),
        len(type_b),
        len(type_a) + len(type_b) == len(classes),
        (len(classes), len(type_a), len(type_b))
        == (b156.CLASS_COUNT, b156.TYPE_A_COUNT, b156.TYPE_B_COUNT),
    )

    # -----------------------------------------------------------------------
    # the CONE-WIDE symbolic carriers.  TYPE B carries FOUR independent free
    # magnitudes -- the checker's generalisation of the primary's two.
    # -----------------------------------------------------------------------
    p1, p2, p3, p4 = sp.symbols("p1 p2 p3 p4", positive=True)
    qa, qb, qc, qd = sp.symbols("qa qb qc qd", positive=True)
    MAGNITUDES = (p1, p2, p3, p4, qa, qb, qc, qd)

    def cone_gram(kind: str, sign: int) -> sp.Matrix:
        s = sp.Integer(sign)
        if kind == "A":
            values = {b_10: s * p1, b_12: s * p2, b_30: s * p3, b_32: s * p4}
        else:
            values = {b_31: s * qa, b_33: s * qb, b_11: s * qc, b_13: s * qd}
        return sp.expand(prime.xreplace({v: values.get(v, 0) for v in ODD}))

    BRANCH_KEYS = (("A", 1), ("A", -1), ("B", 1), ("B", -1))
    CONE_GRAMS = {branch: cone_gram(*branch) for branch in BRANCH_KEYS}

    # Eight exact-rational magnitude points.  They are chosen so that the ONE
    # quantity in this runner whose sign the cone lock does NOT fix -- the
    # value of G' on span(1), which is the only other S_8-invariant subspace --
    # is driven to BOTH signs on BOTH types, so "sign-indefinite" is exhibited
    # rather than assumed.  No inertia measured here depends on the choice.
    SAMPLE_POINTS = (
        (1, 1, 1, 1, 1, 1, 1, 1),
        (1, 2, 3, 5, 5, 3, 2, 1),
        (7, 3, 1, 2, 1, 2, 7, 3),
        (R(1, 2), R(1, 3), R(2, 5), R(3, 7), R(5, 3), 4, R(1, 2), R(1, 7)),
        (2, 2, 5, 5, 3, 3, 8, 8),
        (R(9, 4), 6, R(1, 6), 11, 6, R(2, 9), 13, R(1, 5)),
        (5, 1, 1, 5, 1, 5, 5, 1),
        (R(3, 8), R(8, 3), R(5, 2), R(2, 5),
         R(7, 2), R(2, 7), R(9, 2), R(2, 9)),
    )

    def sample(branch, point) -> sp.Matrix:
        return sp.expand(
            CONE_GRAMS[branch].xreplace(dict(zip(MAGNITUDES, point)))
        )

    SAMPLES = {
        branch: tuple(sample(branch, point) for point in SAMPLE_POINTS)
        for branch in BRANCH_KEYS
    }

    # -----------------------------------------------------------------------
    # C: the incidence operator on the gravity side, and contract C-1
    # -----------------------------------------------------------------------
    Z = sp.Matrix.hstack(
        *(sp.eye(HALF)[:, j] - sp.eye(HALF)[:, HALF - 1] for j in range(7))
    )

    def incidence(edges) -> sp.Matrix:
        columns = []
        for u, v in edges:
            column = sp.zeros(HALF, 1)
            column[v, 0] += 1
            column[u, 0] -= 1
            columns.append(column)
        return sp.Matrix.hstack(*columns) if columns else sp.zeros(HALF, 0)

    cell_index = {c: i for i, c in enumerate(ODD_CELLS)}
    x_edges = [
        (cell_index[(t, x)], cell_index[(t, (x + 1) % 4)])
        for t in (1, 3)
        for x in range(4)
    ]
    t_edges = [(cell_index[(1, x)], cell_index[(3, x)]) for x in range(4)]

    a_torus = incidence(x_edges + t_edges)
    a_sector = incidence(x_edges)
    a_time = incidence(t_edges)
    a_complete = incidence(list(itertools.combinations(range(HALF), 2)))
    origin_of = {c: b145.INDEX[(c[0] % 2, c[1] % 2)] for c in ODD_CELLS}
    pullback = sp.Matrix(
        HALF, 4, lambda i, j: 1 if origin_of[ODD_CELLS[i]] == j else 0
    )
    a_healed = sp.expand(
        pullback
        * sp.Matrix.hstack(
            *(
                sp.eye(4)[:, r] - sp.eye(4)[:, l]
                for l in range(4)
                for r in range(4)
            )
        )
    )
    a_mutant = sp.Matrix(a_torus)
    a_mutant[x_edges[0][0], 0] = 1

    def criterion(A: sp.Matrix) -> tuple:
        """(rank-7 clause, annihilation clause, image clause, rank)."""
        rank = A.rank() if A.cols else 0
        annihilated = A.cols == 0 or zero(sp.expand(ONES * A))
        image_is_z = bool(
            A.cols
            and rank == 7
            and sp.Matrix.hstack(A, Z).rank() == 7
        )
        return (rank == 7, annihilated, image_is_z, rank)

    CANDIDATES = (
        ("A_torus", a_torus, len(x_edges + t_edges)),
        ("A_complete", a_complete, a_complete.cols),
        ("A_sector", a_sector, a_sector.cols),
        ("A_time", a_time, a_time.cols),
        ("A_healed", a_healed, a_healed.cols),
        ("A_mutant", a_mutant, a_mutant.cols),
    )
    incidence_table = tuple(
        (name, edges) + criterion(A) for name, A, edges in CANDIDATES
    )
    torus_clauses = criterion(a_torus)
    incidence_selected = (
        torus_clauses[3],
        torus_clauses[1],
        torus_clauses[2],
        len(x_edges + t_edges),
        Z.rank(),
        HALF - Z.rank(),
        same_space(a_torus, Z),
        same_space(a_torus, kernel_basis(ONES)),
    )
    # each hostile mutant fails a DIFFERENT clause, named
    hostile_controls = (
        # the mutated map: annihilation dies (and with it the image clause)
        (criterion(a_mutant)[1], criterion(a_mutant)[2],
         criterion(a_mutant)[3]),
        # the per-parity-sector restriction: rank 6, image strictly inside Z
        (
            criterion(a_sector)[0],
            criterion(a_sector)[2],
            criterion(a_sector)[3],
            sp.Matrix.hstack(a_sector, Z).rank() == 7,
        ),
        # the time-link-only map: rank 4
        (criterion(a_time)[0], criterion(a_time)[2], criterion(a_time)[3]),
        # the healed-edge origin boundary pulled back: rank 2 AND annihilation
        (
            criterion(a_healed)[0],
            criterion(a_healed)[1],
            criterion(a_healed)[2],
            criterion(a_healed)[3],
        ),
    )
    # CLAUSE THREE IS REDUNDANT.  Measured as an implication over every
    # candidate: rank 7 together with 1^T A = 0 already forces im(A) = ker(1^T)
    # by dimension count, so no candidate can satisfy clauses one and two while
    # failing clause three.  The count of such candidates is the measurement.
    clause_three = (
        sum(
            1
            for _, A, _ in CANDIDATES
            if criterion(A)[0] and criterion(A)[1] and not criterion(A)[2]
        ),
        sum(
            1
            for _, A, _ in CANDIDATES
            if (criterion(A)[0] and criterion(A)[1]) == criterion(A)[2]
        ),
        len(CANDIDATES),
        sum(1 for _, A, _ in CANDIDATES if criterion(A)[2]),
        all(
            same_space(A, Z) for _, A, _ in CANDIDATES if criterion(A)[2]
        ),
    )

    # S_8 STRUCTURE, the sound uniqueness argument, STRENGTHENED.  The
    # permutation representation splits as trivial + standard; the standard
    # summand is irreducible, which is measured by taking the S_8-orbit span of
    # a generic vector of Z and finding all seven dimensions.
    transpositions = []
    for i in range(7):
        matrix = sp.eye(HALF)
        matrix[i, i] = matrix[i + 1, i + 1] = 0
        matrix[i, i + 1] = matrix[i + 1, i] = 1
        transpositions.append(matrix)
    generic = sp.Matrix([1, 2, 4, 8, 16, 32, 64, -127])
    orbit = [generic]
    for _ in range(4):
        grown = list(orbit)
        for matrix in transpositions:
            grown.extend(sp.expand(matrix * v) for v in orbit)
        orbit = grown
        if span_matrix(orbit, HALF).rank() == 7:
            break
    s8_structure = (
        zero(sp.expand(ONES * generic)),
        span_matrix(orbit, HALF).rank(),
        all(same_space(sp.expand(matrix * Z), Z) for matrix in transpositions),
        all(
            zero(sp.expand(ONES * sp.expand(matrix * sp.ones(HALF, 1))
                           - ONES * sp.ones(HALF, 1)))
            for matrix in transpositions
        ),
        S8_INVARIANT_NONTRIVIAL,
    )
    # the OTHER invariant subspace, checked: G' on span(1) is sign-indefinite
    ones_column = sp.ones(HALF, 1)
    span_one_values = tuple(
        sp.simplify(restrict(CONE_GRAMS[branch], ones_column)[0, 0])
        for branch in BRANCH_KEYS
    )
    span_one_indefinite = (
        span_one_values[0],
        all(
            any(
                sp.simplify(
                    value.xreplace(dict(zip(MAGNITUDES, point)))
                ).is_positive
                is True
                for point in SAMPLE_POINTS
            )
            and any(
                sp.simplify(
                    value.xreplace(dict(zip(MAGNITUDES, point)))
                ).is_negative
                is True
                for point in SAMPLE_POINTS
            )
            for value in span_one_values
        ),
        sp.expand(span_one_values[0] - (-p1 - p2 + p3 + p4) / 4) == 0,
        sp.expand(span_one_values[2] - (qa + qb - qc - qd) / 4) == 0,
    )

    # -----------------------------------------------------------------------
    # D: the forced binary, and the measurement that is not forced
    # -----------------------------------------------------------------------
    # certificate planes, exact and CONE-WIDE, both signs of definiteness
    NEG_CERTS = {
        ("A", 1): (E[5] - E[1], E[7] - E[3]),
        ("A", -1): (E[0] - E[1], E[2] - E[3]),
        ("B", 1): (E[1] - E[3], E[4] + E[6] - E[0] - E[2]),
        ("B", -1): (E[1] + E[3] - E[0] - E[2], E[4] - E[6]),
    }
    POS_CERTS = {
        ("A", 1): (E[0] - E[1], E[2] - E[3]),
        ("A", -1): (E[5] - E[1], E[7] - E[3]),
        ("B", 1): (E[1] + E[3] - E[0] - E[2], E[4] - E[6]),
        ("B", -1): (E[1] - E[3], E[4] + E[6] - E[0] - E[2]),
    }

    def definite_plane(branch, vectors, want_negative: bool) -> tuple:
        gram = CONE_GRAMS[branch]
        plane = sp.Matrix.hstack(*vectors)
        reduced = restrict(gram, plane)
        diagonal = (sp.simplify(reduced[0, 0]), sp.simplify(reduced[1, 1]))
        definite = all(
            (entry.is_negative if want_negative else entry.is_positive) is True
            for entry in diagonal
        )
        return (
            zero(sp.expand(ONES * plane)),
            plane.rank(),
            sp.expand(reduced[0, 1]) == 0,
            definite,
            diagonal,
        )

    certificate_planes = tuple(
        (branch, want)
        + definite_plane(
            branch,
            (NEG_CERTS if want == "neg" else POS_CERTS)[branch],
            want == "neg",
        )
        for branch in BRANCH_KEYS
        for want in ("neg", "pos")
    )

    # the unreduced inertia, cone-wide: rank 4 with a definite 2-plane of each
    # sign pins it to (2,4,2) for ALL cone magnitudes, no sampling
    full_inertia_cone_wide = (
        tuple(CONE_GRAMS[branch].rank() for branch in BRANCH_KEYS),
        tuple(
            congruence_inertia(SAMPLES[branch][0]) for branch in BRANCH_KEYS
        ),
        all(
            congruence_inertia(matrix) == FULL_INERTIA
            for branch in BRANCH_KEYS
            for matrix in SAMPLES[branch]
        ),
        b156.FORCED_INERTIA,
    )

    # THE FORCED BINARY.  codim(Z) = 1 and n_-(G') = 2, so Sylvester's
    # inequality n_-(G|_W) >= n_-(G) - codim(W) gives a FLOOR of 1 on EVERY
    # codimension-one subspace whatsoever: the registered PASS branch (a
    # NONZERO reduced Gram with ZERO negative index) was unreachable.  The
    # floor is measured, and the bound is exercised on random codim-1
    # subspaces that have nothing to do with the criterion.
    generator = random.Random(20260820)
    random_codim_one = []
    while len(random_codim_one) < RANDOM_CODIM_ONE_SUBSPACES:
        row = sp.Matrix(
            [[generator.randint(-4, 4) for _ in range(HALF)]]
        )
        if zero(row):
            continue
        basis = kernel_basis(row)
        if basis.cols == 7:
            random_codim_one.append(basis)
    observed = []
    for basis in random_codim_one:
        for branch in BRANCH_KEYS:
            observed.append(
                congruence_inertia(restrict(SAMPLES[branch][0], basis))[2]
            )
    pass_reachability = (
        HALF - Z.rank(),
        FULL_INERTIA[2],
        max(0, FULL_INERTIA[2] - (HALF - Z.rank())),
        min(observed),
        sum(
            1
            for value in observed
            if value < FULL_INERTIA[2] - (HALF - Z.rank())
        ),
        len(observed),
    )

    # THE MEASUREMENT.  Cone-wide, by proof: n_- >= 2 and n_+ >= 2 from the
    # exhibited definite planes inside Z; n_- <= 2 and n_+ <= 2 because a
    # restriction can never raise either index above the unreduced value.  So
    # G'|_Z is exactly (2, 3, 2) and the reduction removes NOTHING.
    reduced_cone_wide = (
        all(entry[2] for entry in certificate_planes),        # planes in Z
        all(entry[3] == 2 for entry in certificate_planes),   # rank 2
        all(entry[4] for entry in certificate_planes),        # cross term zero
        all(entry[5] for entry in certificate_planes),        # definite
        tuple(
            congruence_inertia(restrict(SAMPLES[branch][0], Z))
            for branch in BRANCH_KEYS
        ),
        all(
            congruence_inertia(restrict(matrix, Z)) == REDUCED_INERTIA
            for branch in BRANCH_KEYS
            for matrix in SAMPLES[branch]
        ),
        all(
            not zero(restrict(matrix, Z))
            for branch in BRANCH_KEYS
            for matrix in SAMPLES[branch]
        ),
    )

    # -----------------------------------------------------------------------
    # the two admissible witnesses, rebuilt from field data
    # -----------------------------------------------------------------------
    def edge_feasible(key, point):
        vector = sp.Matrix([sp.expand(point[c]) for c in COORDS])
        matrix = sp.Matrix(raw_rows[key])
        constant = sp.Matrix(
            matrix.rows,
            NCOORD,
            lambda i, j: sp.expand(matrix[i, j]).subs(
                {SHEAR_X: 0, SHEAR_T: 0}
            ),
        )
        if not zero(sp.expand(constant * vector)):
            return None
        time_part = sp.Matrix(
            matrix.rows,
            NCOORD,
            lambda i, j: sp.expand(matrix[i, j]).coeff(SHEAR_T, 1),
        )
        space_part = sp.Matrix(
            matrix.rows,
            NCOORD,
            lambda i, j: sp.expand(matrix[i, j]).coeff(SHEAR_X, 1),
        )
        time_values = sp.expand(time_part * vector)
        space_values = sp.expand(space_part * vector)
        ratio = None
        for row in range(time_values.rows):
            a, b = time_values[row], space_values[row]
            if b == 0:
                if a != 0:
                    return None
                continue
            candidate = sp.nsimplify(-a / b)
            if ratio is None:
                ratio = candidate
            elif sp.simplify(ratio - candidate) != 0:
                return None
        return ratio

    def verify_rows(key, point, tau) -> bool:
        vector = sp.Matrix([sp.expand(point[c]) for c in COORDS])
        matrix = sp.expand(
            sp.Matrix(raw_rows[key]).xreplace(
                {SHEAR_X: tau, SHEAR_T: sp.Integer(1)}
            )
        )
        return zero(sp.expand(matrix * vector))

    a_field = {}
    for t in range(4):
        for x in range(4):
            if x % 2 == 1:
                a_field[(t, x)] = (sp.Integer(0), sp.Integer(1))
            elif t % 2 == 0:
                a_field[(t, x)] = (R(1, 3), sp.Integer(3))
            else:
                a_field[(t, x)] = (R(-1, 3), sp.Integer(1))
    a_point = b147.modulus_point(a_field)
    a_gram = sp.expand(prime.xreplace(a_point))
    a_tau = edge_feasible(b156.WITNESS_EDGE, a_point)

    def type_b_field(block0, block1) -> dict:
        """Each block is ((sigma_odd_x, nu_odd_x), nu_even_x).

        Block 0 governs the time rows t = 0, 1 and block 1 the rows t = 2, 3.
        sigma vanishes at EVEN x, which is what puts the even-x moments at zero
        as a TYPE B class demands; the two pure non-shear rows of a TYPE B edge
        cancel term by term on this ansatz, which is why the two time blocks
        are constrained INDEPENDENTLY and the mirror witness exists.
        """
        field = {}
        for t in range(4):
            odd_data, even_nu = block0 if t < 2 else block1
            for x in range(4):
                field[(t, x)] = (
                    odd_data if x % 2 == 1 else (sp.Integer(0), even_nu)
                )
        return field

    block_low = ((R(1, 3), sp.Integer(1)), sp.Integer(1))
    block_high = ((R(1, 2), R(1, 2)), R(2, 3))
    b_field = type_b_field(block_low, block_high)
    b_field_mirror = type_b_field(block_high, block_low)
    b_point = b147.modulus_point(b_field)
    b_point_mirror = b147.modulus_point(b_field_mirror)
    b_gram = sp.expand(prime.xreplace(b_point))
    b_gram_mirror = sp.expand(prime.xreplace(b_point_mirror))
    b_edge = type_b[0][0]
    b_tau = edge_feasible(b_edge, b_point)
    b_tau_mirror = edge_feasible(b_edge, b_point_mirror)

    witnesses = {
        "A": (a_point, a_gram, a_tau),
        "B": (b_point, b_gram, b_tau),
        "Bm": (b_point_mirror, b_gram_mirror, b_tau_mirror),
    }

    # the per-class table at the witnesses
    slot_moment = {}
    for k in LIVE:
        slot_moment[k] = next(
            iter(sp.expand(prime[k, k]).free_symbols & set(ODD))
        )

    def row_formula(k: int):
        t, x = divmod(k, 4)
        return b145.B_MODULUS[(3, x)] if t == 0 else b145.B_MODULUS[(1, x ^ 1)]

    for k in DEAD:
        slot_moment[k] = row_formula(k)
    slot_of = {slot_moment[k]: k for k in range(HALF)}
    PI = sp.Matrix(
        HALF, HALF, lambda i, j: 1 if slot_of[ODD[j]] == i else 0
    )

    def transport(space: sp.Matrix) -> sp.Matrix:
        return sp.expand(PI * space) if space.cols else sp.zeros(HALF, 0)

    per_class = []
    for subset in classes:
        kind = "A" if subset in type_a else "B"
        _, gram_here, _ = witnesses[kind]
        supp = support_space(gram_here)
        v_space = transport(odd_image(subset))
        per_class.append(
            (
                subset,
                kind,
                congruence_inertia(gram_here),
                congruence_inertia(restrict(gram_here, Z)),
                congruence_inertia(restrict(gram_here, meet(Z, supp))),
                meet(Z, v_space).rank(),
            )
        )
    reduced_per_class = (
        len(per_class),
        all(row[2] == FULL_INERTIA for row in per_class),
        all(row[3] == REDUCED_INERTIA for row in per_class),
        all(row[3][2] == REDUCED_NEG_INDEX for row in per_class),
        tuple(sorted({row[3] for row in per_class})),
        a_tau,
        b_tau,
        b_tau_mirror,
        b145.in_admissible_cone(a_field),
        b145.in_admissible_cone(b_field),
        b145.in_admissible_cone(b_field_mirror),
        verify_rows(b156.WITNESS_EDGE, a_point, a_tau),
        verify_rows(b_edge, b_point, b_tau),
        verify_rows(b_edge, b_point_mirror, b_tau_mirror),
    )

    # N versus Z, at three carriers
    n_rows = []
    for label in ("A", "B", "Bm"):
        _, gram_here, _ = witnesses[label]
        negative = negative_eigenspace(gram_here)
        n_rows.append(
            (
                label,
                negative.rank(),
                sp.Matrix.hstack(negative, Z).rank() == Z.rank(),
                meet(negative, Z).rank(),
                principal_cosines(negative, Z),
                len(sp.Matrix(gram_here).nullspace()),
            )
        )
    n_versus_z = tuple(n_rows)

    # -----------------------------------------------------------------------
    # E: the genuinely-open attacks
    # -----------------------------------------------------------------------
    # A(i) QUOTIENT BY THE RADICAL FIRST.  Sylvester's law of inertia says
    # n_+ and n_- are invariants of the form modulo its radical, so quotienting
    # can only remove ZEROS, never negatives.  Measured, not asserted.
    radical_rows = []
    for branch in BRANCH_KEYS:
        for matrix in SAMPLES[branch][:4]:
            form = restrict(matrix, Z)
            rad_dim, quotient_dim, induced = radical_quotient(form)
            radical_rows.append(
                (
                    branch,
                    form.rows,
                    rad_dim,
                    quotient_dim,
                    congruence_inertia(induced),
                    sp.expand(induced.det()) != 0,
                    congruence_inertia(induced)[0::2]
                    == congruence_inertia(form)[0::2],
                )
            )
    radical_quotient_table = (
        len(radical_rows),
        all(row[1] == Z_DIM for row in radical_rows),
        all(row[2] == RADICAL_DIM_Z for row in radical_rows),
        all(row[3] == QUOTIENT_DIM for row in radical_rows),
        tuple(sorted({row[4] for row in radical_rows})),
        all(row[5] for row in radical_rows),
        all(row[6] for row in radical_rows),
    )

    # A(iii) MORE CONSTRAINTS / A SMALLER IMAGE.  Fifteen NAMED variants.
    def rows_of(*vectors) -> sp.Matrix:
        return sp.Matrix([list(v) for v in vectors])

    total = [1] * HALF
    parity_low = [1, 1, 1, 1, 0, 0, 0, 0]
    parity_high = [0, 0, 0, 0, 1, 1, 1, 1]
    per_x = [
        [1 if k in (x, x + 4) else 0 for k in range(HALF)] for x in range(4)
    ]
    live_total = [1 if k in LIVE else 0 for k in range(HALF)]
    dead_total = [1 if k in DEAD else 0 for k in range(HALF)]
    alternating = [(-1) ** k for k in range(HALF)]
    kill_dead = [[1 if k == d else 0 for k in range(HALF)] for d in DEAD]
    kill_live = [[1 if k == l else 0 for k in range(HALF)] for l in LIVE]

    NAMED = (
        ("Z = ker(1^T), the criterion's", rows_of(total)),
        ("span(1), the only other S_8-invariant", None),
        ("per-parity zero-total", rows_of(parity_low, parity_high)),
        ("per-x-column zero-total", rows_of(*per_x)),
        ("LIVE-slot zero-total", rows_of(live_total)),
        ("DEAD-slot zero-total", rows_of(dead_total)),
        ("LIVE and DEAD zero-total", rows_of(live_total, dead_total)),
        (
            "total + parity + per-x",
            rows_of(total, parity_low, parity_high, *per_x),
        ),
        ("alternating total", rows_of(alternating)),
        ("only LIVE slots survive", rows_of(*kill_dead)),
        ("only DEAD slots survive", rows_of(*kill_live)),
        ("Z cap per-parity", rows_of(total, parity_low, parity_high)),
        ("Z cap alternating", rows_of(total, alternating)),
        ("Z cap LIVE-total", rows_of(total, live_total)),
        ("Z cap per-x", rows_of(total, *per_x)),
    )

    def classify(basis: sp.Matrix, branch) -> str:
        """PSD / NEG / zero for one subspace on one branch, over the
        eight exact-rational magnitude samples."""
        if basis.cols == 0:
            return "zero"
        outcomes = set()
        for matrix in SAMPLES[branch]:
            form = restrict(matrix, basis)
            if zero(form):
                outcomes.add("zero")
            elif congruence_inertia(form)[2] == 0:
                outcomes.add("PSD")
            else:
                outcomes.add("NEG")
        if outcomes == {"PSD"}:
            return "PSD"
        if outcomes == {"zero"}:
            return "zero"
        if "NEG" in outcomes and "PSD" in outcomes:
            return "indef"
        return "NEG" if "NEG" in outcomes else "mixed"

    named_rows = []
    for name, rows in NAMED:
        basis = ones_column if rows is None else kernel_basis(rows)
        named_rows.append(
            (
                name,
                HALF - basis.cols,
                tuple(classify(basis, branch) for branch in BRANCH_KEYS),
            )
        )
    named_variants = (
        len(named_rows),
        sum(
            1
            for row in named_rows
            if all(outcome == "PSD" for outcome in row[2])
        ),
        tuple(row[1] for row in named_rows),
        tuple(row[2] for row in named_rows),
    )

    # EXHAUSTIVE over all 28 coordinate-pair kernels {v_i = v_j = 0}, which is
    # the MINIMUM codimension at which positive semidefiniteness is reachable
    # at all, since n_+ + n_0 = 6 on the unreduced Gram.
    pair_rows = []
    for i, j in itertools.combinations(range(HALF), 2):
        basis = kernel_basis(
            rows_of(
                [1 if k == i else 0 for k in range(HALF)],
                [1 if k == j else 0 for k in range(HALF)],
            )
        )
        outcomes = tuple(classify(basis, branch) for branch in BRANCH_KEYS)
        pair_rows.append(((i, j), outcomes))
    psd_anywhere = tuple(
        (row[0], tuple(
            BRANCH_KEYS[k] for k in range(BRANCHES) if row[1][k] == "PSD"
        ))
        for row in pair_rows
        if "PSD" in row[1]
    )
    coordinate_pairs = (
        len(pair_rows),
        sum(
            1
            for row in pair_rows
            if all(outcome == "PSD" for outcome in row[1])
        ),
        len(psd_anywhere),
        tuple(sorted(entry[0] for entry in psd_anywhere)),
        # the two single-branch hits are COMPLEMENTARY halves of the LIVE set
        (
            len(psd_anywhere) == 2
            and set(psd_anywhere[0][0]) | set(psd_anywhere[1][0]) == set(LIVE)
            and not set(psd_anywhere[0][0]) & set(psd_anywhere[1][0])
        ),
        tuple(len(entry[1]) for entry in psd_anywhere),
        FULL_INERTIA[0] + FULL_INERTIA[1],
    )

    # -----------------------------------------------------------------------
    # F: the secondary measurements
    # -----------------------------------------------------------------------
    support_route = (
        all(row[4][2] == SUPPORT_NEG_INDEX for row in per_class),
        tuple(sorted({row[4] for row in per_class if row[1] == "A"})),
        tuple(sorted({row[4] for row in per_class if row[1] == "B"})),
        len(per_class),
    )

    # THE TYPE B RESIDUE.  The transport is FORCED by G' itself, not chosen:
    # the LIVE diagonal pins the four even-x moments onto slots 0, 2, 5, 7,
    # and the dead blocks' own free symbols pin {1,3} to {b_31, b_33} and
    # {4,6} to {b_11, b_13}; the residual within-pair swap fixes pi(V_B)
    # setwise.  So the checker's correction stands: the route is not
    # convention-dependent, and what carries the point is the SIGN.
    zb3 = meet(Z, transport(odd_x))
    symbolic_residue = sp.simplify(
        restrict(
            sp.expand(
                prime.xreplace({b_10: 0, b_12: 0, b_30: 0, b_32: 0})
            ),
            zb3,
        )[0, 0]
    )
    swap_13 = sp.Matrix(
        HALF, HALF, lambda i, j: int(j == {1: 3, 3: 1}.get(i, i))
    )
    swap_46 = sp.Matrix(
        HALF, HALF, lambda i, j: int(j == {4: 6, 6: 4}.get(i, i))
    )
    type_b_residue = (
        zb3.rank(),
        sp.expand(
            symbolic_residue - (b_31 + b_33 - b_11 - b_13) / 4
        ) == 0,
        {slot_moment[1], slot_moment[3]}
        == (sp.expand(prime[1, 3]).free_symbols & set(ODD)),
        {slot_moment[4], slot_moment[6]}
        == (sp.expand(prime[4, 6]).free_symbols & set(ODD)),
        all(
            same_space(sp.expand(swap * space), space)
            for swap in (swap_13, swap_46)
            for space in (Z, transport(even_x), transport(odd_x))
        ),
        span_matrix([sp.eye(HALF)[:, k] for k in (1, 3)], HALF).rank()
        + span_matrix([sp.eye(HALF)[:, k] for k in (4, 6)], HALF).rank(),
        TYPE_B_CLASS_SUPPORT,
    )
    residue_value = restrict(b_gram, zb3)[0, 0]
    residue_mirror = restrict(b_gram_mirror, zb3)[0, 0]
    indefinite_pair = (
        sp.expand(residue_value),
        sp.expand(residue_mirror),
        sp.expand(residue_value + residue_mirror) == 0,
        b_tau == b_tau_mirror,
        b_edge,
        all(sp.expand(b_point[v]) < 0 for v in (b_11, b_13, b_31, b_33)),
        all(sp.expand(b_point_mirror[v]) < 0
            for v in (b_11, b_13, b_31, b_33)),
        all(sp.expand(b_point[v]) == 0 for v in (b_10, b_12, b_30, b_32)),
    )

    # the s = 0 control: the reduction machinery DOES report positivity when
    # positivity is there
    flat = {SHEAR_X: sp.Integer(0), SHEAR_T: sp.Integer(0)}
    cp_field = {}
    for t in range(4):
        for x in range(4):
            if x % 2 == 1:
                shear = sp.Integer(0)
            elif t == 1:
                shear = R(1, 3)
            elif t == 3:
                shear = -R(1, 3)
            else:
                shear = sp.Integer(0)
            cp_field[(t, x)] = (shear, sp.Integer(1))
    cp_point = b147.modulus_point(cp_field)
    cp_gram = sp.expand(prime.xreplace(cp_point))
    s0_control = (
        sum(
            1
            for key in EDGE_KEYS
            if zero(sp.expand(residue[key].xreplace(flat)))
        ),
        b145.in_admissible_cone(cp_field),
        tuple(sp.expand(cp_gram[k, k]) for k in range(HALF)),
        congruence_inertia(cp_gram),
        congruence_inertia(restrict(cp_gram, Z)),
        not zero(restrict(cp_gram, Z)),
        congruence_inertia(
            restrict(cp_gram, meet(Z, support_space(cp_gram)))
        ),
    )

    # -----------------------------------------------------------------------
    # G: the inertness rider
    # -----------------------------------------------------------------------
    def basis_of(matrices):
        stack = sp.Matrix.hstack(*(vectorise(m) for m in matrices))
        reduced, pivots = stack.T.rref()
        size = matrices[0].rows
        return [
            sp.Matrix(
                size, size, lambda i, j: reduced[k, size * i + j]
            )
            for k in range(len(pivots))
        ]

    inertness_rows = []
    for label, point, tau in (
        ("cone", a_point, a_tau),
        ("typeB", b_point, b_tau),
    ):
        tau = sp.Rational(tau)
        substitution = {
            SHEAR_X: sp.numer(tau),
            SHEAR_T: sp.denom(tau),
        }
        K = {
            key: sp.expand(residue[key].xreplace(substitution).xreplace(point))
            for key in EDGE_KEYS
        }
        generators = [K[key] for key in EDGE_KEYS]
        span = sp.Matrix.hstack(*(vectorise(g) for g in generators))
        base_rank = span.rank()
        distinct = len(
            {sp.srepr(sp.expand(K[key])) for key in EDGE_KEYS}
        )
        nonzero_residues = sum(
            1 for key in EDGE_KEYS if not zero(K[key])
        )
        inside = outside = zero_comm = 0
        commuting: list = []
        extra: list = []
        for left, right in itertools.combinations(EDGE_KEYS, 2):
            bracket = sp.expand(K[left] * K[right] - K[right] * K[left])
            if zero(bracket):
                zero_comm += 1
                inside += 1
                commuting.append((left, right))
                continue
            column = vectorise(bracket)
            if sp.Matrix.hstack(span, column).rank() == base_rank:
                inside += 1
            else:
                outside += 1
                extra.append(column)
        closure_rank = (
            sp.Matrix.hstack(span, *extra).rank() if extra else base_rank
        )
        pool = basis_of(generators)
        lie_rank = len(pool)
        for _ in range(8):
            brackets = [
                sp.expand(pool[i] * pool[j] - pool[j] * pool[i])
                for i, j in itertools.combinations(range(len(pool)), 2)
            ]
            brackets = [m for m in brackets if not zero(m)]
            pool = basis_of(pool + brackets) if brackets else pool
            if len(pool) == lie_rank:
                break
            lie_rank = len(pool)
        inertness_rows.append(
            (
                label,
                nonzero_residues,
                distinct,
                base_rank,
                inside + outside,
                outside,
                zero_comm,
                tuple(commuting),
                all(
                    zero(sp.expand(K[left] - K[right]))
                    for left, right in commuting
                ),
                closure_rank,
                lie_rank,
            )
        )
    inertness = tuple(inertness_rows)
    inertness_reading = (
        # NOT first-class: the span is not closed under the bracket
        all(row[5] > 0 and row[9] > row[3] for row in inertness_rows),
        # NOT inert: the generated algebra is an order of magnitude larger
        all(row[10] > row[3] for row in inertness_rows),
        # the four coincidences are the repeated leading zero in the weights
        b156.HEALING_WEIGHTS[0] == b156.HEALING_WEIGHTS[1] == 0,
        all(
            row[7] == tuple(((t, 0), (t, 1)) for t in range(4))
            for row in inertness_rows
        ),
        # the algebra dimension is CARRIER-DEPENDENT, which is the defect
        inertness_rows[0][10] != inertness_rows[1][10],
    )

    # -----------------------------------------------------------------------
    # the off-family carrier sweep, behind --deep and TWICE verified
    # -----------------------------------------------------------------------
    constant_part: dict = {}
    time_part: dict = {}
    space_part: dict = {}
    for key in EDGE_KEYS:
        matrix = sp.Matrix(raw_rows[key])
        constant_part[key] = sp.Matrix(
            matrix.rows,
            NCOORD,
            lambda i, j: sp.expand(matrix[i, j]).subs(
                {SHEAR_X: 0, SHEAR_T: 0}
            ),
        )
        time_part[key] = sp.Matrix(
            matrix.rows,
            NCOORD,
            lambda i, j: sp.expand(matrix[i, j]).coeff(SHEAR_T, 1),
        )
        space_part[key] = sp.Matrix(
            matrix.rows,
            NCOORD,
            lambda i, j: sp.expand(matrix[i, j]).coeff(SHEAR_X, 1),
        )

    def in_committed_family(field) -> bool:
        """The x-parity family the committed gate sweeps: odd-x cells all
        share one datum, even-x cells depend on the TIME PARITY only."""
        odd_data = {field[(t, x)] for t in range(4) for x in (1, 3)}
        if len(odd_data) != 1:
            return False
        for parity in (0, 1):
            even_data = {
                field[(t, x)]
                for t in range(4)
                if t % 2 == parity
                for x in (0, 2)
            }
            if len(even_data) != 1:
                return False
        return True

    def feasible_ratio(key, point):
        """The unique nonzero tau at which a carrier satisfies one edge, else
        None.  Identical in content to edge_feasible, but reading the
        pre-split constant / time / space parts so the sweep does not rebuild
        them per field."""
        vector = sp.Matrix([sp.expand(point[c]) for c in COORDS])
        if not zero(sp.expand(constant_part[key] * vector)):
            return None
        time_values = sp.expand(time_part[key] * vector)
        space_values = sp.expand(space_part[key] * vector)
        ratio = None
        for row in range(time_values.rows):
            a, b = time_values[row], space_values[row]
            if b == 0:
                if a != 0:
                    return None
                continue
            candidate = sp.nsimplify(-a / b)
            if ratio is None:
                ratio = candidate
            elif ratio != candidate:
                return None
        return ratio if ratio != 0 else None

    def block_field(low, high) -> dict:
        field = {}
        for t in range(4):
            odd_data, even_volume = low if t < 2 else high
            for x in range(4):
                field[(t, x)] = (
                    odd_data if x % 2 == 1 else (sp.Integer(0), even_volume)
                )
        return field

    def widening(odd_shears, odd_volumes, even_volumes) -> tuple:
        """ODD-x data AND the EVEN-x volume free per TIME BLOCK.

        A STRICT SUPERSET of the committed x-parity family, which ties all
        four odd-x data to ONE datum and the even-x data to the time PARITY:
        here the two time blocks (t = 0, 1) and (t = 2, 3) are independent, so
        every field with UNEQUAL blocks lies OUTSIDE the committed family and
        is a carrier the committed sweep never reaches.  Odd-x shears are kept
        strictly nonzero on purpose -- a zero there would kill a hyperbolic
        block and give a degenerate Gram rather than a cone carrier.

        The enumeration is two-stage, and the second stage's COMPLETENESS for
        this family is MEASURED rather than assumed: a TYPE B edge's rows
        split into one row per time block, so a paired field is feasible
        exactly when both blocks are feasible on the SAME edge at the SAME
        ratio.  Stage one records each block's own (edge, ratio); stage two
        verifies every ordered pair inside a group with the FULL feasibility
        test, and a CROSS-GROUP control checks that pairs disagreeing on the
        ratio really are infeasible -- which is what makes the pairing an
        enumeration and not a filter.
        """
        blocks = tuple(
            ((shear, volume), even)
            for shear in odd_shears
            for volume in odd_volumes
            for even in even_volumes
        )
        groups: dict = {}
        admissible = 0
        for block in blocks:
            field = block_field(block, block)
            if not b145.in_admissible_cone(field):
                continue
            admissible += 1
            point = b147.modulus_point(field)
            for key in EDGE_KEYS:
                ratio = feasible_ratio(key, point)
                if ratio is not None:
                    groups.setdefault((key, ratio), []).append(block)

        verified = feasible = off_family = psd = 0
        edges_hit: set = set()
        ratios: set = set()
        inertias: dict = {}
        for (key, ratio), members in sorted(groups.items(), key=str):
            for low, high in itertools.product(members, repeat=2):
                field = block_field(low, high)
                if not b145.in_admissible_cone(field):
                    continue
                point = b147.modulus_point(field)
                gram_here = sp.expand(prime.xreplace(point))
                verified += 1
                if zero(gram_here):
                    continue
                if feasible_ratio(key, point) != ratio:
                    continue
                feasible += 1
                edges_hit.add(key)
                ratios.add(ratio)
                triple = congruence_inertia(restrict(gram_here, Z))
                inertias[triple] = inertias.get(triple, 0) + 1
                if triple[2] == 0:
                    psd += 1
                if not in_committed_family(field):
                    off_family += 1

        # the CROSS-GROUP control: blocks that disagree on (edge, ratio) do
        # NOT pair into a feasible carrier, so the grouping loses nothing
        cross_tested = cross_infeasible = 0
        keys = sorted(groups, key=str)
        for left, right in itertools.combinations(keys, 2):
            if cross_tested >= CROSS_CONTROL_BUDGET:
                break
            if left[0] != right[0]:
                continue
            field = block_field(groups[left][0], groups[right][0])
            if not b145.in_admissible_cone(field):
                continue
            cross_tested += 1
            point = b147.modulus_point(field)
            if feasible_ratio(left[0], point) is None:
                cross_infeasible += 1
        return (
            len(blocks),
            admissible,
            verified,
            feasible,
            off_family,
            psd,
            len(edges_hit),
            len(ratios),
            tuple(sorted(inertias.items(), key=str)),
            (cross_tested, cross_infeasible),
        )

    # The even-x volume sets below are closed under w -> 1/(3w).  That is not
    # decoration: on the block ansatz the per-block feasibility ratio is a
    # quadratic in w whose two roots multiply to 1/3 at any fixed ratio, so
    # each closed pair supplies two DIFFERENT blocks that agree on the ratio
    # and therefore pair into a carrier with UNEQUAL time blocks -- exactly
    # the off-family carriers the committed x-parity family cannot express.
    def widening_one() -> tuple:
        return widening(
            (R(1, 3), R(1, 2), R(-1, 3), R(2, 3)),
            (sp.Integer(1), R(1, 2), sp.Integer(2), sp.Integer(3)),
            (sp.Integer(1), R(1, 3), sp.Integer(2), R(1, 6)),
        )

    def widening_two() -> tuple:
        """The second widening shares NO value at all with the first."""
        return widening(
            (R(2, 5), R(3, 4), R(-2, 5), R(-3, 4)),
            (sp.Integer(5), R(1, 5), sp.Integer(4), R(1, 4)),
            (sp.Integer(5), R(1, 15), R(2, 5), R(5, 6)),
        )

    off_family = None
    if deep:
        off_family = (widening_one(), widening_two())

    correction_arithmetic = (
        CORRECTION_FACTS[0],
        CORRECTION_FACTS[1],
        CORRECTION_FACTS[2],
        CORRECTION_FACTS[1] + sp.Rational(CORRECTION_FACTS[2], 2)
        < CORRECTION_FACTS[0],
        sp.Rational(3, 2),
    )

    exact_no_float = no_float(
        (
            prime,
            Z,
            a_torus,
            a_gram,
            b_gram,
            b_gram_mirror,
            cp_gram,
            a_tau,
            b_tau,
            residue_value,
            residue_mirror,
            symbolic_residue,
        )
    )

    return Facts(
        main_head=main_head,
        authority=authority,
        inertia_calibration=inertia_calibration,
        inertia_routes_agree=inertia_routes_agree,
        seam_reproduced=seam_reproduced,
        class_split=class_split,
        full_inertia_cone_wide=full_inertia_cone_wide,
        incidence_table=incidence_table,
        incidence_selected=incidence_selected,
        hostile_controls=hostile_controls,
        clause_three=clause_three,
        s8_structure=s8_structure,
        span_one_indefinite=span_one_indefinite,
        pass_reachability=pass_reachability,
        certificate_planes=certificate_planes,
        reduced_cone_wide=reduced_cone_wide,
        reduced_per_class=reduced_per_class,
        n_versus_z=n_versus_z,
        radical_quotient_table=radical_quotient_table,
        named_variants=named_variants,
        coordinate_pairs=coordinate_pairs,
        off_family=off_family,
        support_route=support_route,
        type_b_residue=type_b_residue,
        indefinite_pair=indefinite_pair,
        s0_control=s0_control,
        inertness=inertness,
        inertness_reading=inertness_reading,
        correction_arithmetic=correction_arithmetic,
        exact_no_float=exact_no_float,
        scope=scope_certificate(raw_note()),
    )


