# ---------------------------------------------------------------------------
# claims: the only thing a mutation is allowed to touch
# ---------------------------------------------------------------------------
def build_claims(mutation: str) -> dict:
    claims: dict = {
        "main_head": CURRENT_MAIN,
        "parent_pin": "resolved",
        "type_b_count": TYPE_B_COUNT,
        "incidence_rank": INCIDENCE_RANK,
        "clause3_independent": CLAUSE3_INDEPENDENT_CANDIDATES,
        "reduced_neg_index": REDUCED_NEG_INDEX,
        "codim_one_negative_floor": SYLVESTER_FLOOR,
        "quotient_inertia": QUOTIENT_INERTIA,
        "cone_wide_psd_subspaces": CONE_WIDE_PSD_SUBSPACES,
        "residue_pair": RESIDUE_PAIR,
        "s0_reduced_inertia": S0_REDUCED_INERTIA,
        "commutators_outside": COMMUTATORS_OUTSIDE,
        "lie_dims": LIE_DIMS,
        "required_scope_keys": SCOPE_KEYS,
    }
    if mutation == "stale_main_authority":
        claims["main_head"] = STALE_MAIN
    elif mutation == "stale_parent_authority":
        claims["parent_pin"] = "stale"
    elif mutation == "break_class_split":
        claims["type_b_count"] = TYPE_B_COUNT - 1
    elif mutation == "break_incidence_rank":
        claims["incidence_rank"] = INCIDENCE_RANK + 1
    elif mutation == "claim_criterion_clause3_independent":
        # the redundancy denied: clause three asserted to cut something
        claims["clause3_independent"] = 1
    elif mutation == "claim_reduction_removes_a_negative":
        # the whole point of the gate, asserted the other way
        claims["reduced_neg_index"] = REDUCED_NEG_INDEX - 1
    elif mutation == "claim_pass_was_reachable":
        # the pre-registration asserted well-posed: a zero floor on codim 1
        claims["codim_one_negative_floor"] = 0
    elif mutation == "claim_radical_quotient_positive":
        claims["quotient_inertia"] = (QUOTIENT_DIM, 0, 0)
    elif mutation == "claim_codim2_psd_exists":
        claims["cone_wide_psd_subspaces"] = 1
    elif mutation == "break_indefinite_pair":
        # the residue asserted sign-DEFINITE: both carriers the same sign
        claims["residue_pair"] = (RESIDUE_PAIR[0], RESIDUE_PAIR[0])
    elif mutation == "break_s0_control":
        claims["s0_reduced_inertia"] = REDUCED_INERTIA
    elif mutation == "claim_first_class":
        # the commutators asserted to close on the generating span
        claims["commutators_outside"] = 0
    elif mutation == "claim_inert":
        # the generated algebra asserted to stay at the generating span
        claims["lie_dims"] = (RESIDUE_SPAN_DIM, RESIDUE_SPAN_DIM)
    elif mutation == "drop_correction_in_successor":
        # the 1.5-facts correction dropped from the note's required scope;
        # gate H catches the missing keys
        claims["required_scope_keys"] = tuple(
            key
            for key in SCOPE_KEYS
            if key
            not in (
                "one_and_a_half_facts",
                "correction_in_successor",
                "parity_selection_rule",
            )
        )
    elif mutation == "drop_n5_fence":
        claims["required_scope_keys"] = tuple(
            key for key in SCOPE_KEYS if key != "n5_verbatim"
        )
    return claims


